/**
 * Statistics service facade.
 *
 * Endpoint reference: web-bff/api/v1/statistics
 */

import {
  StatisticsPeriod,
  type PersonalGoal,
} from '../../models/Statistics';
import { statisticsEndpoint } from './endpoint';
import type { CreateGoalRequest, UpdateGoalRequest } from './requestModel';

export const statisticsService = {
  getStatistics: (period: StatisticsPeriod) =>
    statisticsEndpoint.getStatistics(period),

  getGoals: () => statisticsEndpoint.getGoals(),

  createGoal: (goal: Omit<PersonalGoal, 'id' | 'progress' | 'current'>) =>
    statisticsEndpoint.createGoal({
      title:       goal.title,
      description: goal.description,
      target:      goal.target,
      unit:        goal.unit,
      deadline:    goal.deadline,
      category:    goal.category,
    } satisfies CreateGoalRequest),

  updateGoal: (goalId: string, updates: Partial<PersonalGoal>) =>
    statisticsEndpoint.updateGoal(goalId, updates as UpdateGoalRequest),

  deleteGoal: (goalId: string) => statisticsEndpoint.deleteGoal(goalId),

  getInsights: () => statisticsEndpoint.getInsights(),

  getAchievements: () => statisticsEndpoint.getAchievements(),

  exportReport: (period: StatisticsPeriod) =>
    statisticsEndpoint.exportReport(period),
};
