import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ToastProvider, ReduxToastContainer } from './components/common/Toast';
import { AlertProvider } from './components/common/Alert';
import { ProtectedRoute } from './components/auth/ProtectedRoute';
import { AppLayout } from './components/layout/AppLayout';
import LoginPage from './pages/LoginPage';
import DashboardStaffPage from './pages/DashboardStaffPage';
import DashboardManagerPage from './pages/DashboardManagerPage';
import TicketsListPage from './pages/TicketsListPage';
import TicketDetailPage from './pages/TicketDetailPage';
import TasksListPage from './pages/TasksListPage';
import TaskDetailPage from './pages/TaskDetailPage';
import TaskPoolPage from './pages/TaskPoolPage';
import DepartmentTasksPage from './pages/DepartmentTasksPage';
import ApprovalsPage from './pages/ApprovalsPage';
import { SLAAlertsPage } from './pages/SLAAlertsPage';
import ReportsPage from './pages/ReportsPage';
import StatisticsPage from './pages/StatisticsPage';
import HistoryPage from './pages/HistoryPage';
import SettingsPage from './pages/SettingsPage';
import UsersManagementPage from './pages/UsersManagementPage';
import DepartmentsManagementPage from './pages/DepartmentsManagementPage';
import AccountsManagementPage from './pages/AccountsManagementPage';
import PermissionsManagementPage from './pages/PermissionsManagementPage';
import { HelpCenterPage } from './pages/HelpCenterPage';
import { WorkflowsPage } from './pages/WorkflowsPage';
import { FAQPage } from './pages/FAQPage';
import { ContactPage } from './pages/ContactPage';
import { NotificationGuidePage } from './pages/NotificationGuidePage';
import { InstallAppGuidePage } from './pages/InstallAppGuidePage';
import NotFoundPage from './pages/NotFoundPage';
import UnauthorizedPage from './pages/UnauthorizedPage';
import SessionExpiredPage from './pages/SessionExpiredPage';
import MedicalIncidentsListPage from './pages/MedicalIncidentsListPage';
import MedicalIncidentFormPage from './pages/MedicalIncidentFormPage';
import MedicalIncidentReportPage from './pages/MedicalIncidentReportPage';
import FallLocationWarningListPage from './pages/FallLocationWarningListPage';
import FallLocationWarningFormPage from './pages/FallLocationWarningFormPage';
import ServiceMismatchReportPage from './pages/ServiceMismatchReportPage';
import FallIncidentReportPage from './pages/FallIncidentReportPage';
import DailyIncidentReportsListPage from './pages/DailyIncidentReportsListPage';
import DailyIncidentReportFormPage from './pages/DailyIncidentReportFormPage';
import NotificationsPage from './pages/NotificationsPage';
import MessagesPage from './pages/MessagesPage';
import { signalRService } from './services/signalr';
import { appSettings } from './config/appSettings';
import { registerRefreshSuccessCallback } from './services/api';
import { updateUserFromRefresh } from './store/slices/authSlice';
import { mapAuthUser } from './services/auth/mapper';
import { store } from './store/store';


const App: React.FC = () => {
  // Get base path from Vite config (set during build)
  const basename = import.meta.env.BASE_URL;

  // Register the silent token-refresh callback once on app mount.
  // When a background token refresh returns updated user data (e.g. defaultMenuUrl
  // changed by admin), map the raw server response and update the Redux store so
  // the UI reflects the change without requiring a re-login.
  useEffect(() => {
    registerRefreshSuccessCallback((raw) => {
      if (raw.user) {
        const updatedUser = mapAuthUser(raw.user as Parameters<typeof mapAuthUser>[0]);
        store.dispatch(updateUserFromRefresh(updatedUser));
      }
    });
  }, []);

  // Start SignalR connection when a token is present (persisted login or new login).
  // Stop the connection when the token is removed (logout).
  useEffect(() => {
    if (!appSettings.enableSignalR) return;

    const token = localStorage.getItem('auth_token');
    if (token) {
      signalRService.start().catch((err) =>
        console.warn('[App] SignalR start failed on mount:', err),
      );
    }

    // Listen for storage events so logout in another tab also disconnects here.
    const onStorage = (e: StorageEvent) => {
      if (e.key !== 'auth_token') return;
      if (e.newValue) {
        signalRService.start().catch(() => {/* ignore */});
      } else {
        signalRService.stop().catch(() => {/* ignore */});
      }
    };
    window.addEventListener('storage', onStorage);
    return () => {
      window.removeEventListener('storage', onStorage);
      // Do not call signalRService.stop() here — this component never truly unmounts
      // in a production SPA.  The storage listener above handles disconnect on logout.
    };
  }, []);

  return (
    <AlertProvider>
      <ToastProvider>
        {/* Renders toasts dispatched via dispatch(addToast(...)) from uiSlice */}
        <ReduxToastContainer />
        <Router basename={basename} future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
          <Routes>
            <Route path="/login" element={<LoginPage />} />
            <Route
              path="/"
              element={
                <ProtectedRoute>
                  <AppLayout />
                </ProtectedRoute>
              }
            >
              <Route index element={<Navigate to="/tickets" replace />} />
              <Route path="dashboard" element={<DashboardStaffPage />} />
              <Route
                path="dashboard/manager"
                element={<DashboardManagerPage />}
              />
              <Route path="tickets" element={<TicketsListPage />} />
              <Route path="tickets/:id" element={<TicketDetailPage />} />
              <Route path="tasks" element={<TasksListPage />} />
              <Route path="tasks/:id" element={<TaskDetailPage />} />
              <Route path="task-pool" element={<TaskPoolPage />} />
              <Route path="department-tasks" element={<DepartmentTasksPage />} />
              <Route
                path="approvals"
                element={<ApprovalsPage />}
              />
              <Route
                path="sla-alerts"
                element={<SLAAlertsPage />}
              />
              <Route
                path="reports"
                element={<ReportsPage />}
              />
              <Route path="statistics" element={<StatisticsPage />} />
              <Route path="history" element={<HistoryPage />} />
              <Route path="settings" element={<SettingsPage />} />
              <Route path="admin/users" element={<UsersManagementPage />} />
              <Route path="admin/departments" element={<DepartmentsManagementPage />} />
              <Route path="admin/accounts" element={<AccountsManagementPage />} />
              <Route path="admin/permissions" element={<PermissionsManagementPage />} />
              <Route path="help" element={<HelpCenterPage />} />
              <Route path="help/workflows" element={<WorkflowsPage />} />
              <Route path="help/faq" element={<FAQPage />} />
              <Route path="help/contact" element={<ContactPage />} />
              <Route path="help/notification-guide" element={<NotificationGuidePage />} />
              <Route path="help/install-app" element={<InstallAppGuidePage />} />
              {/* Notifications */}
              <Route path="notifications" element={<NotificationsPage />} />
              {/* Messages Inbox */}
              <Route path="messages" element={<MessagesPage />} />
              <Route path="messages/:entityType/:entityId" element={<MessagesPage />} />
              {/* Medical Incident Management */}
              <Route path="medical-incidents" element={<MedicalIncidentsListPage />} />
              <Route path="medical-incidents/reports" element={<MedicalIncidentReportPage />} />
              <Route path="medical-incidents/reports/service-mismatch" element={<ServiceMismatchReportPage />} />
              <Route path="medical-incidents/reports/fall" element={<FallIncidentReportPage />} />
              <Route path="medical-incidents/new" element={<MedicalIncidentFormPage />} />
              <Route path="medical-incidents/:id" element={<MedicalIncidentFormPage />} />
              {/* Daily Incident Reports */}
              <Route path="medical-incidents/daily-reports" element={<DailyIncidentReportsListPage />} />
              <Route path="medical-incidents/daily-reports/new" element={<DailyIncidentReportFormPage />} />
              {/* Fall Location Warnings */}
              <Route path="fall-location-warnings" element={<FallLocationWarningListPage />} />
              <Route path="fall-location-warnings/new" element={<FallLocationWarningFormPage />} />
              <Route path="fall-location-warnings/:id" element={<FallLocationWarningFormPage />} />
            </Route>
            {/* Public error routes */}
            <Route path="/unauthorized" element={<UnauthorizedPage />} />
            <Route path="/session-expired" element={<SessionExpiredPage />} />

            {/* Catch-all: 404 for unknown paths */}
            <Route path="*" element={<NotFoundPage />} />

          </Routes>
        </Router>
      </ToastProvider>
    </AlertProvider>
  );
};

export default App;
