import React, { useState, useRef, useEffect } from 'react';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './ButtonList.module.css';

export interface ButtonListProps {
  children: React.ReactNode;
  mainButtonIndex?: number; // Index of the button to always show first when collapsing (default: 0)
  className?: string;
}

/**
 * ButtonList Component
 *
 * Responsive button container with smart overflow:
 * - Desktop: shows up to 3 buttons inline; 4+ collapses extras into ⋮ dropdown
 * - Mobile:  shows up to 2 buttons inline; 3+ collapses extras into ⋮ dropdown
 *
 * The button at `mainButtonIndex` is always one of the visible buttons.
 * Remaining visible slots are filled by the other buttons in their original order.
 */
export const ButtonList: React.FC<ButtonListProps> = ({
  children,
  mainButtonIndex = 0,
  className = '',
}) => {
  const { isMobile } = useResponsive();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Convert children to array, filtering out nulls/booleans from conditional rendering
  const childArray = React.Children.toArray(children);
  const buttonCount = childArray.length;

  // Max visible buttons before collapsing to dropdown
  const maxVisible = isMobile ? 2 : 3;
  const needsDropdown = buttonCount > maxVisible;

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    if (isDropdownOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isDropdownOpen]);

  // All buttons fit — show normally
  if (!needsDropdown) {
    return (
      <div className={`${isMobile ? styles.buttonListFill : styles.buttonList} ${className}`}>
        {children}
      </div>
    );
  }

  // Collapse: main button is always visible; fill remaining slots from other buttons
  const safeMainIndex = Math.min(mainButtonIndex, buttonCount - 1);
  const mainButton = childArray[safeMainIndex];
  const otherButtons = childArray.filter((_, i) => i !== safeMainIndex);

  const visibleOthers = otherButtons.slice(0, maxVisible - 1);
  const dropdownButtons = otherButtons.slice(maxVisible - 1);

  return (
    <div className={`${styles.buttonListCollapse} ${className}`} ref={dropdownRef}>
      {/* Visible buttons: main + up to (maxVisible-1) others */}
      <div className={styles.visibleButtons}>
        <div className={styles.visibleItem}>{mainButton}</div>
        {visibleOthers.map((btn, i) => (
          <div key={i} className={styles.visibleItem}>{btn}</div>
        ))}
      </div>

      {/* Overflow toggle ⋮ */}
      <button
        className={styles.dropdownToggle}
        onClick={() => setIsDropdownOpen((prev) => !prev)}
        type="button"
        aria-label="Thêm hành động"
        aria-expanded={isDropdownOpen}
      >
        <i className={`fas fa-ellipsis-v ${styles.dropdownIcon}`}></i>
      </button>

      {/* Dropdown menu */}
      {isDropdownOpen && (
        <div className={styles.dropdownMenu}>
          {dropdownButtons.map((button, index) => (
            <div
              key={index}
              className={styles.dropdownItem}
              onClick={() => setIsDropdownOpen(false)}
            >
              {button}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

