import React, { useState } from 'react';
import { useAppDispatch } from '../../../store/hooks';
import { assignTicket } from '../../../store/slices/ticketsSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { UserSearchInput } from '../../common/UserSearchInput';
import styles from './AssignTicketModal.module.css';

export interface AssignTicketModalProps {
  isOpen: boolean;
  ticketId: UUID;
  ticketTitle: string;
  onClose: () => void;
  onSuccess?: () => void;
}

export const AssignTicketModal: React.FC<AssignTicketModalProps> = ({
  isOpen,
  ticketId,
  ticketTitle,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const [selectedUserId, setSelectedUserId] = useState('');
  const [selectedUserName, setSelectedUserName] = useState('');
  const [selectedStaffId, setSelectedStaffId] = useState('');
  const [loading, setLoading] = useState(false);

  const handleUserChange = (userId: string, staffId: string, fullName: string) => {
    setSelectedUserId(userId);
    setSelectedStaffId(staffId);
    setSelectedUserName(fullName);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedUserId) {
      dispatch(
        addToast({
          message: 'Vui lòng chọn người xử lý',
          type: 'error',
        })
      );
      return;
    }

    setLoading(true);

    try {
      await dispatch(
        assignTicket({
          ticketId,
          userId:   selectedUserId as UUID,
          userName: selectedUserName,
        })
      ).unwrap();

      dispatch(
        addToast({
          message: 'Phân công phiếu yêu cầu thành công',
          type: 'success',
        })
      );

      setSelectedUserId('');
      setSelectedUserName('');
      setSelectedStaffId('');
      onClose();
      if (onSuccess) {
        onSuccess();
      }
    } catch (error: any) {
      dispatch(
        addToast({
          message: error.message || 'Không thể phân công phiếu yêu cầu',
          type: 'error',
        })
      );
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setSelectedUserId('');
    setSelectedUserName('');
    setSelectedStaffId('');
    onClose();
  };

  const handleConfirmAssign = () => {
    handleSubmit(new Event('submit') as any);
  };

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleCancel} 
      title="Phân công phiếu yêu cầu"
      width="500px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: 'Phân công',
        rightAction: handleConfirmAssign,
        rightDisabled: loading,
      }}
    >
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.ticketInfo}>
          <p className={styles.label}>Phiếu yêu cầu:</p>
          <p className={styles.ticketTitle}>{ticketTitle}</p>
        </div>

        <div className={styles.field}>
          <UserSearchInput
            label="Người xử lý"
            required
            value={selectedUserId}
            staffId={selectedStaffId}
            fullName={selectedUserName}
            onChange={handleUserChange}
            showNameInput={false}
            placeholder="Tìm theo mã hoặc tên nhân viên..."
            disabled={loading}
          />
        </div>
      </form>
    </Slideout>
  );
};
