import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';

const BASE = '/incident-locations';

export interface IncidentLocationDto {
  id:        string;
  name:      string;
  type:      string;
  createdAt: string;
}

export interface IncidentLocationPagedResult {
  items:      IncidentLocationDto[];
  total:      number;
  page:       number;
  pageSize:   number;
  totalPages: number;
}

export interface GetIncidentLocationsParams {
  search?:   string;
  /** "room" | "specific_location" — omit for all */
  type?:     string;
  page?:     number;
  pageSize?: number;
}

export const incidentLocationEndpoint = {
  search: async (params: GetIncidentLocationsParams = {}): Promise<IncidentLocationPagedResult> => {
    const qs = new URLSearchParams();
    if (params.search)   qs.set('search',   params.search);
    if (params.type)     qs.set('type',     params.type);
    qs.set('page',     String(params.page     ?? 1));
    qs.set('pageSize', String(params.pageSize ?? 20));

    const res = await apiClient.get<BffResponse<IncidentLocationPagedResult>>(
      `${BASE}?${qs}`
    );
    return unwrap(res);
  },

  create: async (name: string, type: string): Promise<IncidentLocationDto> => {
    const res = await apiClient.post<BffResponse<IncidentLocationDto>>(BASE, { name, type });
    return unwrap(res);
  },
};
