import React from 'react';
import { StatsCard, StatsCardsGrid } from '../../../../components/common';

export interface TicketStats {
  total: number;
  submitted: number;
  inProgress: number;
  resolved: number;
  closed: number;
}

export interface TicketStatsCardsProps {
  stats: TicketStats;
  loading?: boolean;
}

export const TicketStatsCards: React.FC<TicketStatsCardsProps> = ({ stats, loading }) => {
  return (
    <StatsCardsGrid>
      <StatsCard label="Tất cả" value={stats.total} variant="total" loading={loading} />
      <StatsCard label="Submitted" value={stats.submitted} variant="primary" loading={loading} />
      <StatsCard label="In Progress" value={stats.inProgress} variant="warning" loading={loading} />
      <StatsCard label="Đã xử lý" value={stats.resolved} variant="success" loading={loading} />
      <StatsCard label="Closed" value={stats.closed} variant="gray" loading={loading} />
    </StatsCardsGrid>
  );
};
