import React, { useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { fetchAllDashboardData } from '../../store/slices/dashboardSlice';
import styles from './DashboardStaffPage.module.css';
import { StatsCard, StatsCardsGrid } from '../../components/common';
import { QuickActions } from '../../components/dashboard/QuickActions';
import { MyWorkList } from '../../components/dashboard/MyWorkList';
import { RecentActivity } from '../../components/dashboard/RecentActivity';
import { TodaysDeadlines } from '../../components/dashboard/TodaysDeadlines';
import { QuickAction } from '../../models/Dashboard';

const quickActions: QuickAction[] = [
  { id: 'create-ticket', icon: 'fas fa-plus', label: 'Tạo Ticket Mới', variant: 'primary', route: '/tickets/create' },
  { id: 'task-pool', icon: 'fas fa-swimming-pool', label: 'Xem Công việc chờ nhận', variant: 'secondary', route: '/task-pool' },
  { id: 'history', icon: 'fas fa-clock', label: 'Lịch Sử Công Việc', variant: 'secondary', route: '/history' },
  { id: 'reports', icon: 'fas fa-chart-bar', label: 'Báo Cáo Của Tôi', variant: 'secondary', route: '/reports' },
];

const DashboardStaffPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { stats, workItems, activities, schedule, loading } = useAppSelector(
    (state) => state.dashboard
  );

  // Fetch initial dashboard data
  useEffect(() => {
    const timer = setTimeout(() => { dispatch(fetchAllDashboardData()); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch]);

  // TODO: MQTT Real-time Updates Integration (Phase 3)
  // When MQTT backend is ready, uncomment and implement:
  /*
  useEffect(() => {
    // Import mqttService
    // import { mqttService } from '../../services/mqttService';
    
    // Subscribe to dashboard updates
    const unsubscribeStats = mqttService.subscribe('dashboard/stats', (message) => {
      dispatch(updateStats(message));
    });
    
    const unsubscribeWork = mqttService.subscribe('dashboard/work', (message) => {
      // Handle work item updates
      dispatch(fetchMyWork());
    });
    
    const unsubscribeActivity = mqttService.subscribe('dashboard/activity', (message) => {
      dispatch(addActivity(message));
    });
    
    // Cleanup subscriptions
    return () => {
      unsubscribeStats();
      unsubscribeWork();
      unsubscribeActivity();
    };
  }, [dispatch]);
  */

  // Format date for today's schedule
  const today = new Date();
  const formattedDate = today.toLocaleDateString('vi-VN', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });

  return (
    <div className={styles.dashboard}>
      {/* Page Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-tachometer-alt" />
          Bảng Điều Khiển
        </h1>
      </div>

      {/* Stats Cards */}
      <StatsCardsGrid>
        <StatsCard
          icon="fas fa-ticket-alt"
          variant="primary"
          label="Phiếu Yêu Cầu Đang Xử Lý"
          value={stats?.openTicketsCount ?? 0}
          loading={loading}
        />
        <StatsCard
          icon="fas fa-check-circle"
          variant="success"
          label="Tasks Đang Làm"
          value={stats?.inProgressTasksCount ?? 0}
          loading={loading}
        />
        <StatsCard
          icon="fas fa-exclamation-triangle"
          variant="warning"
          label="Cảnh Báo SLA"
          value={stats?.slaWarningsCount ?? 0}
          loading={loading}
        />
        <StatsCard
          icon="fas fa-star"
          variant="success"
          label="Đánh Giá Trung Bình"
          value={stats?.averageRating ? `${stats.averageRating}/5` : '0/5'}
          loading={loading}
        />
      </StatsCardsGrid>

      {/* Quick Actions */}
      <QuickActions actions={quickActions} />

      {/* Main Content Grid */}
      <div className={styles.contentGrid}>
        {/* Left Column - My Work */}
        <div className={styles.leftColumn}>
          <MyWorkList workItems={workItems} />
        </div>

        {/* Right Column - Activity & Schedule */}
        <div className={styles.rightColumn}>
          <RecentActivity activities={activities} />
        </div>
      </div>

      {/* Today's Schedule - Full Width */}
      <TodaysDeadlines scheduleItems={schedule} date={formattedDate} />
    </div>
  );
};

export default DashboardStaffPage;
