/**
 * Tab 1 — Thống kê SCYK được báo cáo
 *
 * Charts:
 *  • Bar chart   — Số sự cố theo tháng
 *  • Doughnut ×5 — byReportType, byReportingDepartment, byDepartment,
 *                  byOccurrenceStatus, bySeverity
 *  • H-Bar       — byAffectedSubject
 */
import React, { useEffect } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar, Doughnut } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  BAR_OPTIONS_HORIZONTAL,
} from '../chartUtils';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
}

/** Build a Doughnut dataset from ChartDataItem[] */
const toDoughnutData = (items: ChartDataItem[]) => ({
  labels: items.map((d) => d.label),
  datasets: [
    {
      data: items.map((d) => d.count),
      backgroundColor: CHART_COLORS.slice(0, items.length),
      borderWidth: 2,
      borderColor: '#fff',
    },
  ],
});

export const Tab1ReportedStats: React.FC<Props> = ({ report }) => {
  // Register on first render only
  useEffect(() => { /* registration already done above */ }, []);

  // ── Bar: by month ────────────────────────────────────────────────────────
  const monthBarData = {
    labels: report.byMonth.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: report.byMonth.map((d) => d.count),
        backgroundColor: '#0ea5e9',
        borderRadius: 5,
        borderSkipped: false,
      },
    ],
  };

  // ── Horizontal bar: by affected subject ──────────────────────────────────
  const subjectBarData = {
    labels: report.byAffectedSubject.map((d) => d.label),
    datasets: [
      {
        label: 'Số lượng',
        data: report.byAffectedSubject.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, report.byAffectedSubject.length),
        borderRadius: 4,
      },
    ],
  };

  return (
    <div>
      {/* Row 1: Monthly bar chart (full width) */}
      <div className={`${s.grid1} ${s.chartCard}`} style={{ marginBottom: 16 }}>
        <h3><i className="fas fa-chart-bar" /> Số sự cố y khoa theo tháng</h3>
        <Bar data={monthBarData} options={BAR_OPTIONS_VERTICAL} />
      </div>

      {/* Row 2: 3 doughnuts */}
      <div className={s.grid3} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-tag" /> Hình thức báo cáo</h3>
          <Doughnut data={toDoughnutData(report.byReportType)} options={DOUGHNUT_OPTIONS} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-hospital" /> Khoa báo cáo</h3>
          <Doughnut data={toDoughnutData(report.byReportingDepartment)} options={DOUGHNUT_OPTIONS} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-building" /> Khoa xảy ra sự cố</h3>
          <Doughnut data={toDoughnutData(report.byDepartment)} options={DOUGHNUT_OPTIONS} />
        </div>
      </div>

      {/* Row 3: 2 doughnuts + horizontal bar */}
      <div className={s.grid3}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-check-circle" /> Tình trạng xảy ra</h3>
          <Doughnut data={toDoughnutData(report.byOccurrenceStatus)} options={DOUGHNUT_OPTIONS} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-exclamation-triangle" /> Mức độ nghiêm trọng</h3>
          <Doughnut data={toDoughnutData(report.bySeverity)} options={DOUGHNUT_OPTIONS} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-user-injured" /> Đối tượng bị ảnh hưởng</h3>
          <Bar data={subjectBarData} options={BAR_OPTIONS_HORIZONTAL} />
        </div>
      </div>
    </div>
  );
};
