import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { reopenTicket } from '../../../store/slices/ticketsSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { TextArea } from '../../common/TextArea';
import styles from './ReopenTicketModal.module.css';

export interface ReopenTicketModalProps {
  isOpen: boolean;
  ticketId: UUID;
  onClose: () => void;
  onSuccess?: () => void;
}

export const ReopenTicketModal: React.FC<ReopenTicketModalProps> = ({
  isOpen,
  ticketId,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const ticket   = useAppSelector((s) => s.tickets.selectedTicket);
  const [reason, setReason] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) setReason('');
  }, [isOpen]);

  const handleSubmit = async () => {
    if (!reason.trim()) {
      dispatch(addToast({ message: 'Vui lòng nhập lý do mở lại phiếu', type: 'error' }));
      return;
    }
    setLoading(true);
    try {
      await dispatch(reopenTicket({ ticketId, reason: reason.trim() })).unwrap();
      dispatch(addToast({ message: 'Mở lại phiếu yêu cầu thành công', type: 'success' }));
      onClose();
      onSuccess?.();
    } catch (err: any) {
      dispatch(addToast({ message: err?.message || 'Không thể mở lại phiếu yêu cầu', type: 'error' }));
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setReason('');
    onClose();
  };

  return (
    <Slideout
      isOpen={isOpen}
      onClose={handleCancel}
      title="Mở Lại Phiếu Yêu Cầu"
      width="520px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: loading ? 'Đang xử lý...' : 'Xác nhận mở lại',
        rightAction: handleSubmit,
        rightDisabled: loading,
      }}
    >
      <div className={styles.form}>
        {ticket && (
          <div className={styles.summary}>
            <p className={styles.summaryLabel}>Phiếu yêu cầu</p>
            <p className={styles.summaryTitle}>{ticket.title}</p>
          </div>
        )}

        <div className={styles.field}>
          <label className={styles.label}>
            Lý do mở lại <span className={styles.required}>*</span>
          </label>
          <TextArea
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Nêu rõ lý do vì sao cần mở lại phiếu này..."
            rows={5}
            disabled={loading}
          />
          <span className={styles.hint}>Bắt buộc — giải thích lý do mở lại phiếu.</span>
        </div>
      </div>
    </Slideout>
  );
};
