import React from 'react';
import { UUID } from '../../../models/common';
import { format } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './ActivityTab.module.css';

export enum ActivityType {
  CREATED = 'created',
  ASSIGNED = 'assigned',
  STATUS_CHANGED = 'status_changed',
  PROGRESS_UPDATED = 'progress_updated',
  PRIORITY_CHANGED = 'priority_changed',
  COMMENT_ADDED = 'comment_added',
  ATTACHMENT_ADDED = 'attachment_added',
  DUE_DATE_CHANGED = 'due_date_changed',
  SUBTASK_COMPLETED = 'subtask_completed',
  SLA_WARNING = 'sla_warning',
  SLA_BREACH = 'sla_breach',
}

export interface Activity {
  id: UUID;
  entityId: UUID; // Can be ticketId or taskId
  type: ActivityType;
  actor: string;
  description: string;
  timestamp: string;
  metadata?: Record<string, any>;
}

export interface ActivityTabProps {
  entityId: UUID;
  entityType: 'ticket' | 'task';
  activities?: Activity[];
}

export const ActivityTab: React.FC<ActivityTabProps> = ({
  entityId: _entityId,
  entityType: _entityType,
  activities = [],
}) => {
  const formatTimestamp = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInHours = (now.getTime() - date.getTime()) / (1000 * 60 * 60);

    if (diffInHours < 24) {
      return format(date, 'HH:mm', { locale: vi });
    } else if (diffInHours < 48) {
      return 'Hôm qua lúc ' + format(date, 'HH:mm', { locale: vi });
    } else {
      return format(date, 'dd/MM/yyyy HH:mm', { locale: vi });
    }
  };

  const getActivityIcon = (type: ActivityType): string => {
    const iconMap: Record<ActivityType, string> = {
      [ActivityType.CREATED]: 'fa-plus-circle',
      [ActivityType.ASSIGNED]: 'fa-user-tag',
      [ActivityType.STATUS_CHANGED]: 'fa-exchange-alt',
      [ActivityType.PROGRESS_UPDATED]: 'fa-chart-line',
      [ActivityType.PRIORITY_CHANGED]: 'fa-flag',
      [ActivityType.COMMENT_ADDED]: 'fa-comment',
      [ActivityType.ATTACHMENT_ADDED]: 'fa-paperclip',
      [ActivityType.DUE_DATE_CHANGED]: 'fa-calendar',
      [ActivityType.SUBTASK_COMPLETED]: 'fa-check-square',
      [ActivityType.SLA_WARNING]: 'fa-exclamation-triangle',
      [ActivityType.SLA_BREACH]: 'fa-exclamation-circle',
    };
    return iconMap[type] || 'fa-info-circle';
  };

  const getActivityColor = (type: ActivityType): string => {
    const colorMap: Record<ActivityType, string> = {
      [ActivityType.CREATED]: '#10b981',
      [ActivityType.ASSIGNED]: '#3b82f6',
      [ActivityType.STATUS_CHANGED]: '#8b5cf6',
      [ActivityType.PROGRESS_UPDATED]: '#06b6d4',
      [ActivityType.PRIORITY_CHANGED]: '#f59e0b',
      [ActivityType.COMMENT_ADDED]: '#6366f1',
      [ActivityType.ATTACHMENT_ADDED]: '#ec4899',
      [ActivityType.DUE_DATE_CHANGED]: '#f59e0b',
      [ActivityType.SUBTASK_COMPLETED]: '#10b981',
      [ActivityType.SLA_WARNING]: '#f59e0b',
      [ActivityType.SLA_BREACH]: '#ef4444',
    };
    return colorMap[type] || '#6b7280';
  };

  return (
    <div className={styles.activityTab}>
      {activities.length === 0 ? (
        <div className={styles.emptyState}>
          <i className="fas fa-history fa-3x"></i>
          <p>Chưa có hoạt động nào</p>
        </div>
      ) : (
        <div className={styles.timeline}>
          {activities.map((activity, index) => (
            <div key={activity.id} className={styles.timelineItem}>
              <div
                className={styles.timelineMarker}
                style={{ backgroundColor: getActivityColor(activity.type) }}
              >
                <i className={`fas ${getActivityIcon(activity.type)}`}></i>
              </div>
              {index < activities.length - 1 && <div className={styles.timelineLine}></div>}
              <div className={styles.timelineContent}>
                <div className={styles.activityHeader}>
                  <span className={styles.actor}>{activity.actor}</span>
                  <span className={styles.description}>{activity.description}</span>
                </div>
                <div className={styles.timestamp}>
                  <i className="fas fa-clock"></i> {formatTimestamp(activity.timestamp)}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
