/**
 * Formatting utility functions for Task Detail Page
 */

/**
 * Format SLA time from minutes to human-readable string
 * @param minutes - Remaining time in minutes
 * @returns Formatted string (e.g., "2h 30m" or "3 ngày")
 */
export const formatSLATime = (minutes?: number): string => {
  if (!minutes) return 'N/A';
  if (minutes < 60) return `${minutes}m`;
  if (minutes < 1440) return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
  return `${Math.floor(minutes / 1440)} ngày`;
};

/**
 * Generate initials from full name
 * @param name - Full name (e.g., "Nguyễn Văn A")
 * @returns Initials (e.g., "NA")
 */
export const getInitials = (name: string): string => {
  if (!name) return '?';
  const parts = name.split(' ');
  if (parts.length >= 2) {
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  }
  return name.substring(0, 2).toUpperCase();
};
